INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62341916', 62341916, 'analyze_legacy', 'Provinsi DKI Jakarta', 'provinsi', 'DINAS PENANGGULANGAN KEBAKARAN DAN PENYELAMATAN', 'Penyediaan  PJLP Museum Pemadam Kebakaran', 'Jasa Lainnya', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Pusat (Kota)', 140315786, 'December 2025', 'APBD', 1, 1, '2 Orang x 13 Bulan', '- Merekomendasikan Kebijakan edukasi dan penyampaian informasi koleksi museum Pemadam Kebakaran -Melaksanakan program edukasi di museum berbasis penguatan karakter -Melaksanakan program edukasi di museum untuk pengunjung umum -Melaksanakan edukasi di museum untuk peserta berkebutuhan khusus dan pengunjung penyandang disabilitas -Melakukan penyampaian informasi koleksi Museum Pemadam Kebakaran', 'A. PERSYARATAN UMUM 1. Warga Negara Indonesia (WNI); 2. Diutamakan memiliki Kartu Tanda Penduduk (KTP) Daerah Khusus Ibukota Jakarta; 3. Berusia paling sedikit 18 (Delapan belas) tahun; maksimal 56 tahun per 1Januari 2026; 4. Memiliki Nomor Pokok Wajib Pajak (NPWP); 5. Melampirkan Surat Lamaran yang ditujukan kepada Pejabat Pengadaan Dinas Penanggulangan Kebakaran Dan Penyelamatan Provinsi DKI Jakarta, dan memilih hanya 1 (satu) formasi kebutuhan yang diminati; 6. Melampirkan Daftar Riwayat Hidup/Curriculum Vitae (CV); 7. Melampirkan Fotocopy Ijazah dan Transkip Nilai 8. Melampirkan Foto berwarna ukuran 4x6 sebanyak 2 (dua) lembar background merah; 9. Melampirkan Surat Keterangan Catatan Kepolisian (SKCK) dari Kepolisian Republik Indonesia yang masih berlaku; 10. Melampirkan Surat Keterangan Sehat dari Puskesmas/RS Pemerintah yang masih berlaku; 11. Memiliki kartu BPJS Kesehatan; B. PERSYARATAN KHUSUS 1) Laki-laki/Perempuan, 2) berbadan sehat jasmani dan rohani; 3) Pendidikan minimal S1; 4) Di utamakan pernah mengikuti Diklat Teknis Pemadam Kebakaran Kualifikasi Pemadam 1 5.Diutamakan memiliki sertifikat kompetensi Edukator Museum ; 5) Diutamakan yang telah berkontrak sebagai petugas Museum Tahun 2025 dan memiliki Penilaian Prestasi Kinerja Tahun 2025 di Dinas Penanggulangan Kebakaran dan Penyelamatan dengan penilaian kategori Baik; dan 6) Surat pernyataan bersedia menerima upah berdasarkan ketentuan yang berlaku di Provinsi DKI Jakarta.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 441556);
