INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('63010240', 63010240, 'analyze_legacy', 'Pusat Pelaporan Dan Analisis Transaksi Keuangan', 'central', 'PUSAT PELAPORAN DAN ANALISIS TRANSAKSI KEUANGAN', 'Pengadaan Jasa Pembasmi Hama pada Gedung Pusat Pelaporan dan Analisis Transaksi Keuangan Tahun Anggaran 2026', 'Jasa Lainnya', 'E-Purchasing', 'DKI Jakarta, Jakarta Pusat (Kota)', 66600000, 'January 2026', 'APBN - RUPIAH MURNI (A)', 0, 1, '24 Treatment', 'Jasa Pembasmi Hama pada Gedung Pusat Pelaporan dan Analisis Transaksi Keuangan Tahun 2026 sebanyak 24 Treatement', 'Treatment dilakukan 2 kali dalam sebulan (setiap 2 minggu sekali) . Penerapan pengendalian hama lingkungan secara terpadu dengan berbagai metode pengendalian yang kompatibel serta aman bagi manusia dan lingkungan a. Pengendalian Hama di Gedung PPATK, meliputi: 1) Tikus 2) Semut 3) Kecoa 4) Nyamuk 5) Lalat b. Pelaksanaan pekerjaan mencakup seluruh area Gedung PPATK di Jalan Juanda No.35, tapi tidak terbatas pada yang disebutkan dibawah ini: 1) Basemen 2) Masjid dan Ruang Serbaguna 3) Lantai 1-6 4) Saluran got 5) Tempat sampah 6) Halaman depan 7) Halaman belakang c. Metode treatment pengendalian hama dengan cold fogging, spraying residual, gel baiting, unit monitoring hoy hoy trap, metode rodent baiting dan rodent trapping. Selain itu dilukakan monitoring terhadap area perkembangbiakan tikus di area dalam. Pelayanan: 1) Garansi pekerjaan selama periode kontrak berupa treatment ulang pada area yang masih terdapat hama tanpa ada tambahan biaya, apabila setelah dilakukan treatment sesuai dengan jadwal yang disepakati masih ditemukan masala