INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('64005403', 64005403, 'analyze_legacy', 'Provinsi DKI Jakarta', 'provinsi', 'PUSKESMAS TEBET', 'Belanja Jasa Pest Control BLUD Puskesmas Tebet TA 2026', 'Jasa Lainnya', 'E-Purchasing', 'DKI Jakarta, Jakarta Selatan (Kota)', 60000000, 'January 2026', 'BLUD', 1, 1, '1 tahun', 'Jasa Pest dan Rodent Control: Treatment dilaksanakan dengan 4x kunjungan dalam 1 bulan di gedung Puskesmas Tebet dengan durasi waktu 3.5 Jam. Setiap weekend 1x dalam sebulan melakukan General treatment Pest & Rodent Control di area gedung Puskesmas Tebet; Pest Control : dilakukan dengan 1. Metode coldfogging (fogging berbahan dasar air) untuk mengendalikan serangga terbang seperti nyamuk di seluruh area dalam rumah, 2. Metode spraying yang digunakan untuk mengendalikan serangga merayap pada area dalam dan luar seperti toilet, 3. Metode hotfogging (fogging berbahan dasar solar) yang digunakan untuk mengendalikan serangga terbang pada area luar, 4. Metode Gel baiting (pengumpanan) yang digunakan untuk mengendalikan kecoa spesies jerman., 5. Metode Monitoring yang digunakan untuk memonitor infestasi atau perkembangan hama merayap sepert kecoa, Bahan dan Alat : - Zeta cypermethrin , - Lamda cyhalothrin, - Fipronil ; Jasa: Emergency service / keluhan akan direspon maksimal 1 x 24 jam.', 'Jasa Pest dan Rodent Control: Treatment dilaksanakan dengan 4x kunjungan dalam 1 bulan di gedung Puskesmas Tebet dengan durasi waktu 3.5 Jam. Setiap weekend 1x dalam sebulan melakukan General treatment Pest & Rodent Control di area gedung Puskesmas Tebet; Pest Control : dilakukan dengan 1. Metode coldfogging (fogging berbahan dasar air) untuk mengendalikan serangga terbang seperti nyamuk di seluruh area dalam rumah, 2. Metode spraying yang digunakan untuk mengendalikan serangga merayap pada area dalam dan luar seperti toilet, 3. Metode hotfogging (fogging berbahan dasar solar) yang digunakan untuk mengendalikan serangga terbang pada area luar, 4. Metode Gel baiting (pengumpanan) yang digunakan untuk mengendalikan kecoa spesies jerman., 5. Metode Monitoring yang digunakan untuk memonitor infestasi atau perkembangan hama merayap sepert kecoa, Bahan dan Alat : - Zeta cypermethrin , - Lamda cyhalothrin, - Fipronil ; Jasa: Emergency service / keluhan akan direspon maksimal 1 x 24 jam.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 442791);
