INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('65170409', 65170409, 'analyze_legacy', 'Kementerian Perencanaan Pembangunan Nasional', 'central', 'KANTOR MENTERI NEGARA PPN  BAPPENAS', 'Konsultan Junior Analisis Efektivitas Pembiayaan Proyek Pinjaman Luar negeri Lingkup Perserikatan Bangsa - Bangsa', 'Jasa Konsultansi', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Selatan (Kota)', 80400000, 'January 2026', 'APBN - HIBAH LUAR NEGERI (I)', 1, 1, '1 Paket', 'a. Melakukan analisis isu pembangunan berkelanjutan yang sedang berkembang dan genting di tingkat global, nasional, dan subnasional sebagai pedoman memberikan masukan atas rumusan posisi Indonesia pada forum-forum dan sidang/sidang kerja sama pembiayaan internasional, khususnya lingkup PBB; b. Menyiapkan masukan atas saran posisi dan mendukung penyusunan bahan pertemuan; c. Melakukan koordinasi lintas K/L dalam rangka keanggotaan Bappenas pada working group serta lembaga internasional. Mendukung penyusunan bahan pertemuan; d. Melakukan koordinasi lintas Unit Kerja di Kementerian PPN/Bappenas dan K/L yang terkait dalam rangka penyusunan dokumen perencanaan dan review kerja sama Pemerintah Indonesia dengan pendanaan internasional; e. Mendukung proses pemantauan dan evaluasi kerja sama pembangunan antara Pemerintah Indonesia dengan mitra pembangunan yang berada di bawah koordinasi Direktorat Pembiayaan dan Hibah Luar Negeri.', '1. Diutamakan menggunakan Tenaga Ahli dalam Negeri, dibuktikan dengan identitas kewarganegaraan Indonesia seperti Kartu Tanda Penduduk (KTP); 2. Memiliki Nomor Pokok Wajib Pajak (NPWP); 3. Pendidikan minimal S1 diutamakan prodi Ilmu Hubungan Internasional, Ilmu Politik, dengan IPK minimal 3,5 dari kampus terakreditasi A, dibuktikan dengan ijazah jenjang pendidikan yang telah ditempuh dan transkrip nilai; 4. Memiliki keterampilan analitis dan konseptual yang kuat, dibuktikan dengan hasil tulisan akademik/laporan formal/surat referensi kerja sebelumnya/sertifikat keahlian/sertifikat pembicara; 5. Memiliki pengetahuan seputar forum kerja sama internasional, dibuktikan dengan hasil tulisan akademik/laporan formal/artikel ilmiah terkait kerja sama internasional; 6. Memiliki kemampuan bahasa Inggris yang kuat, yang dibuktikan dengan IELTS/TOEFL iBT, atau contoh tulisan dalam bahasa Inggris; 7. Mahir menggunakan aplikasi Microsoft Office (Word, PowerPoint, Excel); 8. Mampu bekerja dalam tim dan tenggat waktu yang padat; 9. Tidak akan menuntut kepada PPK untuk diangkat menjadi Aparatur Sipil Negara (ASN) pada Kementerian PPN/Bappenas; dan 10. Tidak menuntut untuk mendapatkan fasilitas berupa: a. THR dan Gaji 13 b. BPJS Kesehatan c. BPJS Ketenagakerjaan d. Fasilitas kerja berupa perangkat komputer (Seperti Laptop dan PC) dari BMN', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 444846);
