INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('64901800', 64901800, 'analyze_legacy', 'Kota Malang', 'kabkota', 'Bagian Umum', 'Belanja Sewa Kendaraan Dinas Bermotor Perorangan', 'Jasa Lainnya', 'E-Purchasing', 'Jawa Timur, Malang (Kota)', 800000000, 'January 2026', 'APBD', 1, 1, 'Unit / Hari', 'Paket pekerjaan ini merupakan belanja sewa kendaraan dinas bermotor perorangan dari pihak ketiga untuk mendukung kelancaran pelaksanaan tugas dan kegiatan kedinasan. Sewa kendaraan dimaksud digunakan sebagai sarana transportasi operasional dalam menunjang mobilitas kedinasan pejabat/pegawai sesuai kebutuhan unit kerja selama periode sewa.', '1. Penyedia wajib menyediakan kendaraan dinas bermotor perorangan yang laik jalan, terawat, dan siap digunakan untuk mendukung kegiatan kedinasan sesuai kebutuhan unit kerja 2. Kendaraan disediakan sesuai jangka waktu sewa dan jadwal penggunaan yang ditetapkan oleh pengguna jasa 3. Kendaraan yang disewa digunakan untuk keperluan kedinasan dan mengikuti ketentuan serta tata tertib penggunaan kendaraan dinas yang berlaku 4. Penyedia bertanggung jawab atas ketersediaan kendaraan serta pemeliharaan dan kondisi kendaraan selama masa sewa.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 448638);
